`timescale 1ns / 1ps
`default_nettype none

module soc_tb;

    localparam integer REGISTER_COUNT = 16;
    localparam integer MEMORY_WORDS = 256;
    localparam integer DEFAULT_TIMEOUT_CYCLES = 1000;

    reg clock;
    reg reset;
    wire halted;
    wire [31:0] incr_pc;
    wire is_mul;

    reg [1023:0] hex_path;
    reg [1023:0] dump_path;
    integer timeout_cycles;
    integer memory_start;
    integer memory_words;
    integer trace_enabled;
    integer cycle_count;
    integer register_index;
    integer memory_index;
    integer dump_file;
    integer unknown_registers;
    integer out_of_range;

    // Device under test
    soc_top #(
        .INIT_file("")
    ) dut (
        .clock (clock),
        .reset (reset),
        .halted(halted),
        .IncrPC(incr_pc),
        .is_mul(is_mul)
    );

    always #5 clock = ~clock;

    task fail_and_finish;
        input [1023:0] reason;
        begin
            $display("FAIL: %0s", reason);
            $finish;
        end
    endtask

    task dump_state;
        begin
            dump_file = $fopen(dump_path, "w");
            if (dump_file == 0) begin
                fail_and_finish("could not open dump file");
            end

            $fdisplay(dump_file, "MINIMIPS_DUMP_V1");
            $fdisplay(dump_file, "CYCLES %0d", cycle_count);
            $fdisplay(dump_file, "REGISTERS %0d", REGISTER_COUNT);
            for (register_index = 0;
                 register_index < REGISTER_COUNT;
                 register_index = register_index + 1) begin
                $fdisplay(dump_file, "R%0d 0x%08h",
                          register_index, dut.registers.regs[register_index]);
            end

            $fdisplay(dump_file, "MEMORY start=%0d words=%0d",
                      memory_start, memory_words);
            for (memory_index = memory_start;
                 memory_index < memory_start + memory_words;
                 memory_index = memory_index + 1) begin
                $fdisplay(dump_file, "MEM[%0d] 0x%08h",
                          memory_index, dut.data_memory.memory[memory_index]);
            end
            $fclose(dump_file);
        end
    endtask

    initial begin
        clock = 1'b0;
        reset = 1'b1;
        cycle_count = 0;
        unknown_registers = 0;

        hex_path = "sw/hex/smoke.hex";
        dump_path = "build/soc_tb.dump";
        timeout_cycles = DEFAULT_TIMEOUT_CYCLES;
        memory_start = 0;
        memory_words = 16;
        trace_enabled = 0;

        void'($value$plusargs("HEX=%s", hex_path));
        void'($value$plusargs("DUMP=%s", dump_path));
        void'($value$plusargs("TIMEOUT=%d", timeout_cycles));
        void'($value$plusargs("MEM_START=%d", memory_start));
        void'($value$plusargs("MEM_WORDS=%d", memory_words));
        trace_enabled = $test$plusargs("TRACE");

        if (memory_start < 0 ||
            memory_start >= MEMORY_WORDS ||
            memory_words < 0 ||
            memory_start + memory_words > MEMORY_WORDS) begin
            fail_and_finish("invalid memory dump range");
        end

        $display("HEX=%0s", hex_path);
        $display("DUMP=%0s", dump_path);
        $readmemh(hex_path, dut.instruction_memory.memory);

        repeat (2) @(posedge clock);
        #1;
        reset = 1'b0;

        while (cycle_count < timeout_cycles) begin
            @(posedge clock);
            #1;
            cycle_count = cycle_count + 1;

            if (trace_enabled != 0) begin
                $display("TRACE cycle=%0d PC=0x%08h instr=0x%08h halted=%b R0=0x%08h",
                         cycle_count, dut.PC, dut.instruction, halted,
                         dut.registers.regs[0]);
            end

            if (halted === 1'b1) begin
                for (register_index = 0;
                     register_index < REGISTER_COUNT;
                     register_index = register_index + 1) begin
                    if (^dut.registers.regs[register_index] === 1'bx) begin
                        unknown_registers = unknown_registers + 1;
                    end
                end

                if (unknown_registers != 0) begin
                    dump_state();
                    fail_and_finish("unknown register state");
                end

                dump_state();
                $display("cycles=%0d", cycle_count);
                $display("[PASS] soc_tb: halted cleanly");
                $finish;
            end

            if (halted !== 1'b0) begin
                fail_and_finish("halt signal is unknown");
            end
        end

        dump_state();
        fail_and_finish("timeout");
    end

    initial begin
        $dumpfile("waves/soc_tb.vcd");
        $dumpvars(0, soc_tb);
    end

endmodule

`default_nettype wire
